import type { Command } from 'obsidian';
import type { DynamicCommandFamily, StaticCommandId } from '../command-metadata';
import type { CommandHost } from './command-host';

export type DocumentedStaticCommand = Command & { id: StaticCommandId };

const registrationsByHost = new WeakMap<object, Set<string>>();

/**
 * Runtime registration seam for statically documented commands.
 *
 * The ID union is generated by the typed documentation array and therefore
 * disappears from the production bundle. The generator independently rejects
 * raw registrations, stale metadata, duplicate IDs, and name drift.
 */
export function addDocumentedCommand(host: CommandHost, command: DocumentedStaticCommand): void {
  const ids = registrationsByHost.get(host) ?? new Set<string>();
  if (ids.has(command.id)) throw new Error(`Duplicate static command registration: ${command.id}`);
  ids.add(command.id);
  registrationsByHost.set(host, ids);
  host.addCommand(command);
}

/** Register one instance of a separately documented dynamic command family. */
export function addDocumentedDynamicCommand(host: CommandHost, _family: DynamicCommandFamily, command: Command): void {
  host.addCommand(command);
}
